async function trySearch(q: string[]) {
  for (let i = 0; i < 3; i++) {
    try { return await tools.web_search({ queries: q }); }
    catch (e) { if (i === 2) return { error: String(e).slice(0, 400) }; }
  }
}
async function tryFetch(u: string) {
  try { const r = await tools.web_fetch({ url: u }); return { url: u, status: r.statusCode, body: (r.body.content || "").slice(0, 6000) }; }
  catch (e) { return { url: u, error: String(e).slice(0, 300) }; }
}
const [s, gh] = await Promise.all([
  trySearch(["our-free-model DSH 插件", "DeepSeek Harness 免费模型插件 推荐"]),
  tryFetch("https://github.com/Ebony-Vinyl/dsh-our-free-model"),
]);
